<script setup lang="ts">
import { computed, ref } from 'vue'
import { slides } from './deck'
import Icon from './DefenseIcon.vue'
import ProductStage from './ProductStage.vue'
import { parseMoneyToMinor, formatMoney } from '../../utils/money'
const props = defineProps<{ index: number }>()
const emit = defineEmits<{ next: []; jump: [index: number] }>()
const slide = computed(() => slides[props.index]!)
const utterance = ref('午饭 28 元')
const saved = ref(false)
const demoError = ref('')
const parsed = computed(() => {
  const match = utterance.value.match(/(?:^|[^\d.\-])([0-9]+(?:\.[0-9]{1,2})?)(?:\s*元|\s*块|\s*$)/)
  const minor = match ? parseMoneyToMinor(match[1]!) : null
  if (minor === null || minor <= 0 || !Number.isSafeInteger(minor)) return null
  const category = /奶茶|咖啡|午饭|晚饭|早餐/.test(utterance.value) ? '餐饮美食' : /地铁|公交|打车/.test(utterance.value) ? '交通出行' : '其他支出'
  return { minor, category }
})
function record() { if (!parsed.value) { demoError.value = '请输入一笔正数金额，例如“午饭 28 元”。'; return }; saved.value = true; demoError.value = '' }
function sample(text: string) { utterance.value = text; saved.value = false; demoError.value = '' }
</script>
